import{_ as n,o as t,c as i,ag as a}from"./chunks/framework.CrXGS008.js";const f=JSON.parse('{"title":"Besitz","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station-business/ownership.md","filePath":"de/repair-station-business/ownership.md"}'),r={name:"de/repair-station-business/ownership.md"};function s(o,e,d,l,u,g){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="besitz" tabindex="-1">Besitz <a class="header-anchor" href="#besitz" aria-label="Permalink to &quot;Besitz&quot;">​</a></h1><h2 id="eine-station-zum-verkauf-anbieten" tabindex="-1">Eine Station zum Verkauf anbieten <a class="header-anchor" href="#eine-station-zum-verkauf-anbieten" aria-label="Permalink to &quot;Eine Station zum Verkauf anbieten&quot;">​</a></h2><p>Nur Stationen im Verkauf können gekauft werden. Als Admin mit <code>nay_repair_business.config</code>:</p><ol><li>Erstelle deine Stationen mit dem <a href="/de/repair-station/stations">Editor der Repair Station</a>.</li><li>Öffne das Admin-Panel mit <code>/nay:repairbusiness</code> oder über die Aktion <strong>Stationen zum Verkauf verwalten</strong> in <code>/nay</code>.</li><li>Wähle eine Station, gib einen Verkaufspreis ein und drücke <strong>Zum Verkauf stellen</strong>.</li></ol><p>Dieselbe Liste gibt es in <code>/nay</code> als <strong>Stationen zum Verkauf</strong>. Eine Station im Verkauf zeigt einen Kartenmarker und einen Hinweis mit ihrem Preis. Solange niemand sie besitzt, entscheidet <strong>Stationen zum Verkauf ohne Besitzer</strong>, ob sie offen bleibt (Spieler reparieren dort wie gewohnt) oder geschlossen ist, bis jemand sie kauft.</p><h2 id="kaufen" tabindex="-1">Kaufen <a class="header-anchor" href="#kaufen" aria-label="Permalink to &quot;Kaufen&quot;">​</a></h2><p>Der Spieler geht zur Station und drückt <strong>E</strong>. Eine Bestätigung zeigt den Preis und das Konto, von dem bezahlt wird (<strong>Kaufkonto</strong>). Ein Spieler kann bis zu <strong>Stationen pro Spieler</strong> Stationen besitzen. Der Server prüft den Kauf, aus höchstens 8 Metern Entfernung zur Station, und erstattet ihn, wenn etwas schiefgeht.</p><h2 id="das-tablet" tabindex="-1">Das Tablet <a class="header-anchor" href="#das-tablet" aria-label="Permalink to &quot;Das Tablet&quot;">​</a></h2><p>Der Besitzer drückt an der Station <strong>E</strong>, um das Tablet zu öffnen, aus 8 Metern oder weniger:</p><ul><li><strong>Übersicht</strong>: Lager, Kasse, Reparaturen des Tages und der letzten 7 Tage, letzte Vorgänge.</li><li><strong>Lager</strong>: Teile kaufen oder Gegenstände abgeben, siehe <a href="/de/repair-station-business/stock">Lager</a>.</li><li><strong>Kasse</strong>: Geld bar oder auf die Bank abheben oder Geld von der Bank in die Kasse einzahlen.</li><li><strong>Einstellungen</strong>: Preisprozentsatz, Name der Station, Verkauf der Station.</li></ul><p>Der vom Besitzer gewählte Name ersetzt den Stationsnamen im Reparaturmenü. Der Prozentsatz skaliert den Preis jeder Leistung: Spieler sehen den Endpreis vor der Zahlung, und die Steuer (<strong>Steuer</strong>) wird von jeder Zahlung einbehalten, den Rest erhält die Kasse.</p><h2 id="eine-station-verkaufen-und-verlieren" tabindex="-1">Eine Station verkaufen und verlieren <a class="header-anchor" href="#eine-station-verkaufen-und-verlieren" aria-label="Permalink to &quot;Eine Station verkaufen und verlieren&quot;">​</a></h2><ul><li><strong>Verkauf</strong>: Der Besitzer bekommt den Prozentsatz <strong>Rückkauf</strong> des Kaufpreises plus die Kasse auf die Bank. Die Station steht wieder zu ihrem Preis zum Verkauf.</li><li><strong>Entfernen</strong>: Das Team kann einen Besitzer im Admin-Panel entfernen. Er wird wie bei einem Verkauf ausgezahlt.</li><li><strong>Inaktivität</strong>: Ein Besitzer, der das Tablet <strong>Inaktivitätsgrenze</strong> Tage lang nicht öffnet, verliert die Station und wird wie bei einem Verkauf ausgezahlt. 0 schaltet das aus.</li><li><strong>Station gelöscht</strong>: Wird eine Station im Editor der Repair Station gelöscht, wird ihr Besitzer wie bei einem Verkauf ausgezahlt, und die Station verschwindet aus dem System.</li></ul><p>Ein Besitzer, der dabei offline ist, bekommt das Geld einmalig beim nächsten Laden des Charakters, mit einer Benachrichtigung. Jeder Vorgang wird im Protokoll festgehalten, lesbar über die <a href="/de/repair-station-business/api">API</a>.</p>',14)])])}const m=n(r,[["render",s]]);export{f as __pageData,m as default};
